'use strict';
const A=Explorer,$=s=>document.querySelector(s),names={bitcoin:'Bitcoin',gold:'Gold',dxy:'DXY'},colors={bitcoin:'#c4784b',gold:'#b6a06b',dxy:'#6a87a7'},escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=(n,d=2)=>n===null||!Number.isFinite(n)?'—':(n*100).toFixed(d)+'%',num=(n,d=2)=>n===null||!Number.isFinite(n)?'—':n.toFixed(d),signed=n=>n===null?'—':(n>0?'+':'')+pct(n);
const bundled=window.EXPLORER_DATA;let loaded=A.clean(bundled.rows),meta={...bundled.meta},result,conditional,pair='bitcoin_gold',windowSize=90,tail=.1;
function announce(msg){$('#notice').hidden=false;$('#notice').textContent=msg;}
function table(head,rows){return '<table><thead><tr>'+head.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>';}
function metric(label,value,note,color){return `<div class="metric"><div class="metric-label"><i style="background:${color}"></i>${label}</div><strong>${value}</strong><small>${note}</small></div>`;}
function lineChart(target,data,series,opt={}){const el=$(target),w=1000,h=opt.small?215:290,p={l:58,r:30,t:22,b:32};const values=data.flatMap(r=>series.map(s=>r[s.key]).filter(v=>Number.isFinite(v)));if(!values.length){el.innerHTML='<div class="empty">'+(opt.empty||'Not enough observations for this calculation.')+'<small>Try a wider date range or a smaller rolling window.</small></div>';return;}
 let lo=opt.min??Math.min(...values),hi=opt.max??Math.max(...values);if(lo===hi){lo-=1;hi+=1;}if(opt.min===undefined&&opt.max===undefined){const pad=(hi-lo)*.07;lo-=pad;hi+=pad;}const x=i=>p.l+i/Math.max(1,data.length-1)*(w-p.l-p.r),y=v=>h-p.b-(v-lo)/(hi-lo)*(h-p.t-p.b),format=opt.format||((v)=>num(v,0));let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${escape(opt.label||'Time-series chart')}"><title>${escape(opt.label||'Time-series chart')}</title>`;
 for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;svg+=`<line class="grid" x1="${p.l}" y1="${y(v)}" x2="${w-p.r}" y2="${y(v)}"/><text x="${p.l-10}" y="${y(v)+3}" text-anchor="end">${escape(format(v))}</text>`;}if(opt.zero&&lo<0&&hi>0)svg+=`<line x1="${p.l}" y1="${y(0)}" x2="${w-p.r}" y2="${y(0)}" stroke="#bdc2bf" stroke-dasharray="4 5"/>`;
 for(const i of [...new Set([0,Math.floor((data.length-1)/3),Math.floor(2*(data.length-1)/3),data.length-1])])svg+=`<text x="${x(i)}" y="${h-8}" text-anchor="${i===0?'start':i===data.length-1?'end':'middle'}">${data[i].date}</text>`;
 for(const s of series){let path='',started=false;for(let i=0;i<data.length;i++){const v=data[i][s.key];if(v===null||!Number.isFinite(v)){started=false;continue;}path+=(started?'L':'M')+x(i).toFixed(2)+','+y(v).toFixed(2);started=true;}svg+=`<path class="line" d="${path}" stroke="${s.color}"/>`;}svg+='</svg>';el.innerHTML=svg;}
function currentPrices(){return loaded.rows.filter(r=>r.date>=$('#start').value&&r.date<=$('#end').value);}
function render(){const prices=currentPrices();if($('#start').value>$('#end').value)throw Error('Start date must be on or before end date.');const next=A.analyze(prices,windowSize);const stress=A.stress(next.returns,tail);result=next;conditional=stress;$('#notice').hidden=true;const synthetic=meta.kind==='synthetic';$('#source-banner').className='source-banner'+(synthetic?'':' real');$('#source-banner').innerHTML=synthetic?'<strong>ILLUSTRATIVE DEMO — NOT HISTORICAL MARKET DATA</strong> Seeded simulated prices demonstrate the interface. These numbers are not evidence about Bitcoin or gold. Import real prices or run the included R pipeline.':`<strong>${meta.kind==='imported'?'USER-IMPORTED PRICES':'HISTORICAL SNAPSHOT'}</strong> ${escape(meta.source)} · Descriptive analysis of loaded observations; no live feed.`;$('#range-label').textContent=prices[0].date+' — '+prices.at(-1).date+' · '+prices.length.toLocaleString()+' prices / '+next.returns.length.toLocaleString()+' return intervals';const s=next.stats,c=next.matrix.bitcoin.gold;$('#metrics').innerHTML=metric('BITCOIN · TOTAL CHANGE',signed(s.bitcoin.totalReturn),'Within the selected price range',colors.bitcoin)+metric('GOLD · TOTAL CHANGE',signed(s.gold.totalReturn),'Price proxy; excludes trading costs',colors.gold)+metric('BITCOIN · INTERVAL VOLATILITY',pct(s.bitcoin.intervalVolatility),'Sample standard deviation of log returns',colors.bitcoin)+metric('BITCOIN / GOLD · CORRELATION',num(c),'Pearson correlation of log returns','#8e9ba3');renderPrice();lineChart('#drawdown-chart',next.drawdowns,A.assets.map(k=>({key:k,color:colors[k]})),{small:true,max:0,format:v=>pct(v,0),label:'Drawdown of Bitcoin, gold and DXY inside the selected period'});$('#risk-table').innerHTML=table(['Asset','Volatility','Max drawdown','Negative intervals'],A.assets.map(k=>[`<i class="asset-dot" style="background:${colors[k]}"></i>${names[k]}`,pct(s[k].intervalVolatility),pct(s[k].maxDrawdown),pct(s[k].negativeShare,1)]));$('#insight').innerHTML=`<b>${synthetic?'DEMO READING':'SAMPLE READING'}</b><span>Within this selected ${synthetic?'simulated ':''}sample, Bitcoin / Gold return correlation is ${num(c)}. The longest gap between common observations is ${next.maxGap} calendar days. ${synthetic?'Use real observations before drawing financial conclusions.':'Date alignment does not guarantee simultaneous market closes; interpret cross-market co-movement with that limitation.'}</span>`;renderRelationships();renderStress();renderProvenance();}
function renderPrice(){if(!result)return;const log=$('#logscale').checked;const p=result.prices,normal=p.map(r=>Object.fromEntries([['date',r.date],...A.assets.map(k=>[k,log?Math.log10(r[k]/p[0][k]*100):r[k]/p[0][k]*100])]));lineChart('#price-chart',normal,A.assets.map(k=>({key:k,color:colors[k]})),{format:v=>log?new Intl.NumberFormat('en',{maximumFractionDigits:0}).format(10**v):new Intl.NumberFormat('en',{maximumFractionDigits:0}).format(v),label:'Normalised price indices, base 100'+(log?', logarithmic vertical scale':', linear vertical scale')});$('#price-cursor').max=p.length-1;$('#price-cursor').value=Math.min(+$('#price-cursor').value,p.length-1);priceReadout();}
function priceReadout(){if(!result)return;const r=result.prices[+$('#price-cursor').value];$('#price-readout').textContent=r.date+' · '+A.assets.map(k=>names[k]+' '+num(r[k]/result.prices[0][k]*100)).join(' / ');}
function renderRelationships(){const data=result.rolling;lineChart('#rolling-chart',data,[{key:pair,color:pair==='gold_dxy'?colors.dxy:colors.bitcoin}],{min:-1,max:1,zero:true,format:v=>num(v,1),label:windowSize+'-observation trailing return correlation for '+pair.replace('_',' / ')});const valid=data.map(r=>r[pair]).filter(v=>v!==null);$('#rolling-label').textContent=valid.length?windowSize+' observations per window · '+valid.length+' defined estimates · range '+num(Math.min(...valid))+' to '+num(Math.max(...valid)):`Need at least ${windowSize+1} price observations for one full window.`;$('#matrix').innerHTML=table(['',...A.assets.map(k=>names[k])],A.assets.map(k=>[names[k],...A.assets.map(b=>{const v=result.matrix[k][b];return `<span>${num(v)}</span>`;})]));$('#matrix').querySelectorAll('tbody tr').forEach((tr,i)=>tr.querySelectorAll('td').forEach((td,j)=>{if(!j)return;const v=result.matrix[A.assets[i]][A.assets[j-1]];td.style.background=v===null?'#f1f0e9':v>=0?`rgba(155,171,163,${.08+Math.abs(v)*.35})`:`rgba(196,120,75,${.08+Math.abs(v)*.25})`;}));}
function renderStress(){const t=conditional,sim=meta.kind==='synthetic';$('#stress-banner').textContent=sim?'SIMULATED DATA: this selection demonstrates the method. It does not describe actual dollar stress episodes.':'Selected observations are the largest positive DXY-return intervals within this sample, not pre-defined crisis dates.';$('#stress-metrics').innerHTML=metric('SELECTED INTERVALS',t.n,'Of '+result.returns.length+' intervals in range','#7e8c9c')+metric('DXY · TAIL CUTOFF',pct(t.threshold),'Sample '+Math.round((1-tail)*100)+'th percentile of log returns',colors.dxy)+metric('BITCOIN · MEAN TAIL RETURN',pct(t.conditional.bitcoin.meanLogReturn),'Mean log return in selected intervals',colors.bitcoin)+metric('GOLD · MEAN TAIL RETURN',pct(t.conditional.gold.meanLogReturn),'Mean log return in selected intervals',colors.gold);$('#stress-table').innerHTML=table(['Asset','Mean: all','Mean: dollar tail','Negative share: all','Negative share: tail','Corr. with DXY: tail'],['bitcoin','gold'].map(k=>[names[k],pct(t.baseline[k].meanLogReturn),pct(t.conditional[k].meanLogReturn),pct(t.baseline[k].negativeShare,1),pct(t.conditional[k].negativeShare,1),num(t.conditional[k].corrDXY)]));const top=[...t.selected].sort((a,b)=>b.dxy-a.dxy).slice(0,50);$('#tail-table').innerHTML=top.length?table(['Interval ending','Bitcoin log return','Gold log return','DXY log return'],top.map(r=>[r.date,pct(r.bitcoin,3),pct(r.gold,3),pct(r.dxy,3)])):'<div class="empty">No positive dollar-return intervals match this selection.</div>';}
function renderProvenance(){const q=meta.inputQuality||loaded.quality;const info=[['Dataset',meta.title],['Type',meta.kind==='synthetic'?'Synthetic — not market history':meta.kind],['Source',meta.source],['Date coverage',loaded.rows[0].date+' to '+loaded.rows.at(-1).date],['Input / retained',q.inputRows+' / '+q.retainedRows+' price rows'],['Incomplete dates',q.droppedRows+' dropped'],['Alignment',q.policy],['Gold proxy',meta.goldProxy||'Provided by uploader; verify exact instrument'],['Saved / generated',meta.generatedAt||'Not provided'],['Largest gap',result.maxGap+' calendar days in selected range']];$('#provenance').innerHTML=info.map(([k,v])=>`<div><dt>${escape(k)}</dt><dd>${escape(v)}</dd></div>`).join('');}
function setDates(){const r=loaded.rows;for(const id of ['start','end']){$('#'+id).min=r[0].date;$('#'+id).max=r.at(-1).date;}$('#start').value=r[0].date;$('#end').value=r.at(-1).date;}
function apply(){try{render();}catch(e){announce(e.message+' Previous successful analysis is still displayed.');}}
$('.presets').querySelectorAll('button').forEach(b=>b.onclick=()=>{const end=loaded.rows.at(-1).date;$('#end').value=end;if(b.dataset.period==='all')$('#start').value=loaded.rows[0].date;else{const d=new Date(end+'T00:00:00Z');d.setUTCMonth(d.getUTCMonth()-Number(b.dataset.period));$('#start').value=d.toISOString().slice(0,10)>loaded.rows[0].date?d.toISOString().slice(0,10):loaded.rows[0].date;}$('.presets').querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));apply();});$('#apply').onclick=()=>{$('.presets').querySelectorAll('button').forEach(x=>x.classList.remove('selected'));apply();};$('#window').onchange=e=>{windowSize=+e.target.value;apply();};$('#pair').onchange=e=>{pair=e.target.value;renderRelationships();};$('#tail').onchange=e=>{tail=+e.target.value;conditional=A.stress(result.returns,tail);renderStress();};$('#logscale').onchange=renderPrice;$('#price-cursor').oninput=priceReadout;
function download(filename,text,type='text/csv'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#download-prices').onclick=()=>download('explorer-loaded-prices.csv',A.csv([['date',...A.assets],...loaded.rows.map(r=>[r.date,...A.assets.map(k=>r[k])])]));$('#stress-download').onclick=()=>download('explorer-dxy-tail-returns.csv',A.csv([['date','bitcoin_log_return','gold_log_return','dxy_log_return'],...conditional.selected.map(r=>[r.date,r.bitcoin,r.gold,r.dxy])]));$('#export').onclick=()=>download('bitcoin-gold-analysis.json',JSON.stringify({project:'Bitcoin / Gold Explorer',exportedAt:new Date().toISOString(),source:meta,quality:loaded.quality,analysis:{first:result.prices[0].date,last:result.prices.at(-1).date,observations:result.prices.length,returnIntervals:result.returns.length,rollingWindow:windowSize,maxGapCalendarDays:result.maxGap,stats:result.stats,correlation:result.matrix,dxyTail:{fraction:tail,threshold:conditional.threshold,n:conditional.n,conditional:conditional.conditional},methods:{returns:'Natural log price differences between common observations',volatility:'Sample standard deviation, divisor n-1; no annualisation',correlation:'Pearson correlation of log returns; null for undefined variance',alignment:'Complete common observed dates; no forward-fill',drawdown:'Price / running peak - 1, within selected range',stress:'Positive DXY returns >= sample (1-tail) quantile; in-sample descriptive selection'},limitations:['Close-time differences are not eliminated by date joins.','Gold futures are not physical gold.','No causal, predictive or safe-haven classification.']},prices:result.prices},null,2),'application/json');
async function importFile(file){try{if(!file)throw Error('Choose a CSV file.');if(!/\.csv$/i.test(file.name))throw Error('Choose a .csv file.');if(file.size>5*1024*1024)throw Error('Maximum file size is 5 MB.');const parsed=A.parseCSV(await file.text());A.analyze(parsed.rows,windowSize);loaded=parsed;meta={kind:'imported',title:file.name,source:$('#source-note').value.trim()||'User CSV; source not documented',generatedAt:new Date().toISOString(),goldProxy:'User-provided series; instrument not independently verified'};setDates();render();location.hash='overview';}catch(e){announce('Import failed: '+e.message+' Your previous dataset is unchanged.');}}
$('#csv-file').onchange=e=>{importFile(e.target.files[0]);e.target.value='';};const drop=$('#dropzone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag');};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');importFile(e.dataTransfer.files[0]);};$('#reset').onclick=()=>{if(!confirm('Restore the bundled dataset and clear the imported prices?'))return;loaded=A.clean(bundled.rows);meta={...bundled.meta};setDates();render();};
function route(){const hash=location.hash.slice(1),key=['overview','relationships','stress','data'].includes(hash)?hash:'overview';document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==key);document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+key);if(a.hash==='#'+key)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=(key==='overview'?'Bitcoin / Gold Explorer':key[0].toUpperCase()+key.slice(1)+' · Bitcoin / Gold Explorer');}window.addEventListener('hashchange',route);setDates();render();route();
